rule "aruba extract base"
when
  has_field("message") &&
  contains(to_string($message.source), "aruba")
then
  let msg = to_string($message.message);
  let proc = regex("([a-z]+)\\[([0-9]+)\\]:", msg);
  set_field("aruba_process", proc["0"]);
  let eid = regex("<([0-9]+)>\\s+<([A-Z]+)>", msg);
  set_field("aruba_event_id", eid["0"]);
  set_field("aruba_severity", eid["1"]);
  let ap = regex("AP:(\\S+)\\s+<([0-9.]+)\\s+([0-9a-fA-F:]+)>", msg);
  set_field("aruba_ap_name", ap["0"]);
  set_field("aruba_ap_ip", ap["1"]);
  set_field("aruba_ap_mac", ap["2"]);
end

rule "aruba extract station"
when
  has_field("message") &&
  contains(to_string($message.source), "aruba") &&
  contains(to_string($message.message), "mac-")
then
  let msg = to_string($message.message);
  let m = regex("mac-([0-9a-fA-F:]+)", msg);
  set_field("aruba_client_mac", m["0"]);
  let b = regex("bssid-([0-9a-fA-F:]+)", msg);
  set_field("aruba_bssid", b["0"]);
  let e = regex("essid-(\\S+?)(?:\\s|$)", msg);
  set_field("aruba_essid", e["0"]);
end
